run.command:
$ErrorActionPreference = 'SilentlyContinue'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$ifs = (netsh wlan show interfaces 2>&1 | Out-String)
$nets = (netsh wlan show networks mode=bssid 2>&1 | Out-String)
if ($nets -match 'location permission') { 'WIFI-ERROR: Windows 11 will not share Wi-Fi details with any program until Location services are on - being administrator does not bypass this. Open Settings > Privacy & security > Location and turn on both "Location services" and "Let desktop apps access your location", then run this again. (You can turn them off again afterwards.)'; exit 1 }
if ($nets -match 'requires elevation') { 'WIFI-ERROR: this Windows build only lists networks for an administrator. Use "Run as admin" at the top of the window, then run this again.'; exit 1 }
if ($nets -match 'There is no wireless interface|not running|is not supported') { 'WIFI-ERROR: no Wi-Fi adapter is available on this PC (or the WLAN service is not running).'; exit 1 }
# our own connection
$me = @{}
foreach ($line in ($ifs -split "`r?`n")) { if ($line -match '^\s*(SSID|BSSID|Channel|Band|Signal|Radio type|Receive rate \(Mbps\)|Transmit rate \(Mbps\)|Authentication)\s*:\s*(.+?)\s*$') { if (-not $me.ContainsKey($Matches[1])) { $me[$Matches[1]] = $Matches[2] } } }
$myBssid = ([string]$me['BSSID']).ToLower(); $myCh = [int]($me['Channel'] -replace '[^\d]', ''); $mySsid = [string]$me['SSID']
# every access point in range
$aps = @(); $ssid = ''; $auth = ''; $cur = $null
foreach ($line in ($nets -split "`r?`n")) {
  if ($line -match '^SSID \d+\s*:\s*(.*)$') { $ssid = $Matches[1].Trim(); $auth = ''; $cur = $null; continue }
  if ($line -match '^\s+Authentication\s*:\s*(.+?)\s*$' -and -not $cur) { $auth = $Matches[1]; continue }
  if ($line -match '^\s+BSSID \d+\s*:\s*(\S+)') { $cur = [pscustomobject]@{ Network = $ssid; BSSID = $Matches[1].ToLower(); Signal = 0; Channel = 0; Band = ''; Standard = ''; Security = $auth }; $aps += $cur; continue }
  if (-not $cur) { continue }
  if ($line -match '^\s+Signal\s*:\s*(\d+)%') { $cur.Signal = [int]$Matches[1] }
  elseif ($line -match '^\s+Channel\s*:\s*(\d+)') { $cur.Channel = [int]$Matches[1] }
  elseif ($line -match '^\s+Band\s*:\s*(.+?)\s*$') { $cur.Band = $Matches[1] }
  elseif ($line -match '^\s+Radio type\s*:\s*(.+?)\s*$') { $cur.Standard = $Matches[1] -replace '^802\.11', '' }
}
if (-not $aps.Count) { 'WIFI-ERROR: no networks were listed. Make sure Wi-Fi is switched on, then run this again.'; exit 1 }
foreach ($a in $aps) { if (-not $a.Band) { $a.Band = if ($a.Channel -le 14) { '2.4 GHz' } elseif ($a.Channel -ge 36 -and $a.Channel -le 177) { '5 GHz' } else { '6 GHz' } }; if (-not $a.Network) { $a.Network = '(hidden)' } }
function Overlaps($a, $b) { if ($a.Band -ne $b.Band) { return $false }; if ($a.Band -like '2.4*') { return ([math]::Abs($a.Channel - $b.Channel) -le 4) }; return ($a.Channel -eq $b.Channel) }
$mine = $aps | Where-Object { $_.BSSID -eq $myBssid } | Select-Object -First 1
if (-not $mine -and $mySsid) { $mine = $aps | Where-Object { $_.Network -eq $mySsid } | Sort-Object Signal -Descending | Select-Object -First 1 }
$others = @($aps | Where-Object { -not $mine -or $_.BSSID -ne $mine.BSSID })
$strong = @($others | Where-Object { $_.Signal -ge 35 })
'Wi-Fi survey: ' + $aps.Count + ' access points in range on ' + @($aps | Where-Object { $_.Band -like '2.4*' }).Count + ' x 2.4 GHz, ' + @($aps | Where-Object { $_.Band -like '5*' }).Count + ' x 5 GHz, ' + @($aps | Where-Object { $_.Band -like '6*' }).Count + ' x 6 GHz' + (& { if ($mine) { '. You are on "' + $mine.Network + '" (' + $mine.Band + ', channel ' + $mine.Channel + ', ' + $mine.Signal + '% signal' + (& { if ($mine.Standard) { ', Wi-Fi ' + $mine.Standard } else { '' } }) + ')' } else { '. Not connected to Wi-Fi at the moment' } })
''
$rows = foreach ($a in ($aps | Sort-Object Signal -Descending)) { [pscustomobject]@{ Network = $a.Network; Band = $a.Band; Channel = $a.Channel; Signal = ([string]$a.Signal + '%'); Security = $a.Security; Standard = $a.Standard; BSSID = $a.BSSID; Note = (& { if ($mine -and $a.BSSID -eq $mine.BSSID) { 'yours' } elseif ($mySsid -and $a.Network -eq $mySsid) { 'your network, other AP' } elseif ($mine -and (Overlaps $a $mine) -and $a.Signal -ge 35) { 'overlaps your channel' } else { '' } }) } }
($rows | Format-Table -AutoSize | Out-String -Width 4096).TrimEnd()
''
'Channel load (strong networks only, 35%+ signal)'
$bands = @('2.4 GHz', '5 GHz', '6 GHz')
$load = foreach ($b in $bands) { $inBand = @($aps | Where-Object { $_.Band -eq $b -and $_.Signal -ge 35 }); if (-not $inBand.Count) { continue }; $chs = @($inBand | ForEach-Object { $_.Channel } | Sort-Object -Unique); foreach ($ch in $chs) { $probe = [pscustomobject]@{ Band = $b; Channel = $ch }; $n = @($inBand | Where-Object { Overlaps $_ $probe }).Count; [pscustomobject]@{ Band = $b; Channel = $ch; 'Networks on/overlapping' = $n; Names = ((@($inBand | Where-Object { Overlaps $_ $probe } | ForEach-Object { $_.Network } | Sort-Object -Unique) | Select-Object -First 4) -join ', ') } } }
if ($load) { ($load | Format-Table -AutoSize | Out-String -Width 4096).TrimEnd() } else { '  no strong networks' }
''
# verdict
$clash = @(); if ($mine) { $clash = @($strong | Where-Object { Overlaps $_ $mine }) }
$suggest = ''
if ($mine -and $mine.Band -like '2.4*') {
  $best = foreach ($ch in @(1, 6, 11)) { $probe = [pscustomobject]@{ Band = '2.4 GHz'; Channel = $ch }; [pscustomobject]@{ ch = $ch; n = @($strong | Where-Object { Overlaps $_ $probe }).Count } }
  $best = $best | Sort-Object n, ch | Select-Object -First 1
  if ($best.ch -ne $mine.Channel -and $best.n -lt $clash.Count) { $suggest = 'Channel ' + $best.ch + ' has only ' + $best.n + ' strong network' + (& { if ($best.n -ne 1) { 's' } else { '' } }) + ' on or near it; ' + $mine.Channel + ' has ' + $clash.Count + '. Setting the router to channel ' + $best.ch + ' (or to Auto) should help.' }
} elseif ($mine) {
  $seen = @($strong | Where-Object { $_.Band -eq $mine.Band } | ForEach-Object { $_.Channel }); $cands = @(36, 40, 44, 48, 149, 153, 157, 161) | Where-Object { $_ -ne $mine.Channel }
  $free = @($cands | Where-Object { $seen -notcontains $_ }); if ($clash.Count -ge 2 -and $free.Count) { $suggest = 'Nobody strong is on channel ' + $free[0] + '; moving the router there (or to Auto) would give you a clear channel.' }
}
$twoFour = @($aps | Where-Object { $_.Band -like '2.4*' -and $_.Network -eq $mySsid }); $five = @($aps | Where-Object { $_.Band -notlike '2.4*' -and $_.Network -eq $mySsid })
if (-not $mine) { 'Not connected: the table is the neighbourhood as seen from here. Quiet channels are the ones with the fewest strong networks on or overlapping them.' }
elseif ($clash.Count -ge 3) { 'Congested: ' + $clash.Count + ' strong networks share or overlap your channel ' + $mine.Channel + ' on ' + $mine.Band + ' (' + ((@($clash | ForEach-Object { $_.Network } | Sort-Object -Unique) | Select-Object -First 5) -join ', ') + '). They all take turns on the same airtime, so your speed drops when they are busy. ' + $suggest + (& { if ($mine.Band -like '2.4*' -and $five.Count) { ' Your network is also available on 5 GHz here (' + $five[0].Signal + '% signal): that band is faster and far less crowded - prefer it when the signal allows.' } else { '' } }) }
elseif ($mine.Signal -lt 40) { 'Weak signal: ' + $mine.Signal + '% on "' + $mine.Network + '". Below about 40% the link keeps dropping to slower rates and retrying; move closer, or on 2.4 GHz expect better reach at lower speed' + (& { if ($mine.Band -notlike '2.4*' -and $twoFour.Count) { ' - your network is also on 2.4 GHz here at ' + $twoFour[0].Signal + '%.' } else { '.' } }) }
elseif ($clash.Count -gt 0) { 'Fine: ' + $mine.Signal + '% signal on channel ' + $mine.Channel + ' (' + $mine.Band + '); ' + $clash.Count + ' strong network' + (& { if ($clash.Count -ne 1) { 's' } else { '' } }) + ' overlap' + (& { if ($clash.Count -eq 1) { 's' } else { '' } }) + ' it, which is normal in a neighbourhood. ' + $suggest }
else { 'Clear: ' + $mine.Signal + '% signal on channel ' + $mine.Channel + ' (' + $mine.Band + ') with no strong network overlapping it. If Wi-Fi still feels slow, the problem is not the airwaves - try "Why is everything slow?".' }
''
'SUMMARY ' + ([pscustomobject]@{ total = $aps.Count; mine = (& { if ($mine) { $mine.Network } else { '' } }); band = (& { if ($mine) { $mine.Band } else { '' } }); channel = (& { if ($mine) { $mine.Channel } else { 0 } }); signal = (& { if ($mine) { $mine.Signal } else { 0 } }); clash = $clash.Count; suggest = $suggest } | ConvertTo-Json -Compress)

$ErrorActionPreference = 'SilentlyContinue'
$doDown = $true; $doUp = $true; $downCap = 8; $upCap = 8
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
Add-Type -AssemblyName System.Net.Http
$hc = New-Object System.Net.Http.HttpClient; $hc.Timeout = [TimeSpan]::FromSeconds(60)
$base = 'https://speed.cloudflare.com'
function To-Mbps($bytes, $secs) { if ($secs -le 0) { return 0 }; return [math]::Round($bytes * 8 / 1000000 / $secs, 1) }
function To-MB($bytes) { return [math]::Round($bytes / 1000000, 1) }
function Ping-Once($ms) { try { $r = (New-Object System.Net.NetworkInformation.Ping).Send('1.1.1.1', $ms); if ($r.Status -eq 'Success') { return [int]$r.RoundtripTime } } catch { }; return -1 }
function Avg($a) { if ($a.Count) { return [int][math]::Round(($a | Measure-Object -Average).Average) }; return -1 }
# where the test server is, and how we look from outside
$colo = ''; $pubIp = ''
try { $trace = $hc.GetStringAsync($base + '/cdn-cgi/trace').Result; if ($trace -match '(?m)^colo=(\S+)') { $colo = $Matches[1] }; if ($trace -match '(?m)^ip=(\S+)') { $pubIp = $Matches[1] } } catch { }
if (-not $trace) { 'SPEED-ERROR: could not reach speed.cloudflare.com. Check the internet connection first ("Can''t reach the internet?" playbook).'; exit 1 }
'Speed test via Cloudflare' + (& { if ($colo) { ' (server ' + $colo + ')' } else { '' } }) + (& { if ($pubIp) { ', your public address ' + $pubIp } else { '' } })
# idle latency: ICMP to 1.1.1.1, and one HTTP round trip to the test server
$idle = @(); for ($i = 0; $i -lt 5; $i++) { $t = Ping-Once 1000; if ($t -ge 0) { $idle += $t }; Start-Sleep -Milliseconds 150 }
$sw = [Diagnostics.Stopwatch]::StartNew(); try { [void]$hc.GetByteArrayAsync($base + '/__down?bytes=0').Result } catch { }; $httpMs = [int]$sw.ElapsedMilliseconds
$idleAvg = Avg $idle; $jit = 0; if ($idle.Count -gt 1) { $jit = [int](($idle | Measure-Object -Maximum).Maximum - ($idle | Measure-Object -Minimum).Minimum) }
'Idle latency: ' + (& { if ($idleAvg -ge 0) { $idleAvg.ToString() + ' ms to 1.1.1.1 (jitter ' + $jit + ' ms)' } else { 'ping to 1.1.1.1 blocked' } }) + ', ' + $httpMs + ' ms server round trip'
''
$downMbps = 0; $downBytes = 0; $downSecs = 0; $downLoaded = @()
if ($doDown) {
  'Download (' + $downCap + ' s)'
  try {
    # Cloudflare serves at most ~100 MB per request, so ask for 25 MB repeatedly on one kept-alive connection until the time is up
    $buf = New-Object byte[] 262144; $sw = [Diagnostics.Stopwatch]::StartNew(); $total = [long]0; $tick = 1; $lastBytes = [long]0; $lastT = 0.0; $done = $false; $pt = $null
    while (-not $done) {
      $resp = $hc.GetAsync($base + '/__down?bytes=25000000', [System.Net.Http.HttpCompletionOption]::ResponseHeadersRead).Result
      if (-not $resp.IsSuccessStatusCode) { 'Download failed: HTTP ' + [int]$resp.StatusCode; break }
      $stream = $resp.Content.ReadAsStreamAsync().Result
      while (($n = $stream.Read($buf, 0, $buf.Length)) -gt 0) {
        $total += $n; $el = $sw.Elapsed.TotalSeconds
        if ($el -ge $tick) {
          # the ping runs in the background so a lost one never pauses the download; its answer is read at the next tick
          $p = -2; if ($pt) { if ($pt.Status -eq 'RanToCompletion' -and $pt.Result.Status -eq 'Success') { $p = [int]$pt.Result.RoundtripTime; $downLoaded += $p } else { $p = -1 } }
          $pt = (New-Object System.Net.NetworkInformation.Ping).SendPingAsync('1.1.1.1', 900)
          ('{0,3} s  {1,7} MB  {2,7} Mbit/s   {3,-1}' -f $tick, (To-MB $total), (To-Mbps ($total - $lastBytes) ($el - $lastT)), (& { if ($p -ge 0) { 'ping ' + $p + ' ms' } elseif ($p -eq -1) { 'ping lost' } else { '' } }))
          $lastBytes = $total; $lastT = $el; $tick++
        }
        if ($el -ge $downCap) { $done = $true; break }
      }
      $stream.Close(); $resp.Dispose()
    }
    $downSecs = [math]::Round($sw.Elapsed.TotalSeconds, 1); $downBytes = $total
  } catch { 'Download failed: ' + $_.Exception.Message }
  if ($downBytes -gt 0) { $downMbps = To-Mbps $downBytes $downSecs; 'Download: ' + $downMbps + ' Mbit/s  (' + (To-MB $downBytes) + ' MB in ' + $downSecs + ' s)' }
  ''
}
$upMbps = 0; $upBytes = 0; $upSecs = 0; $upLoaded = @()
if ($doUp) {
  'Upload (up to ' + $upCap + ' s)'
  $sizes = @(2000000, 8000000, 25000000, 60000000); $spent = 0.0
  foreach ($size in $sizes) {
    if ($spent -ge $upCap) { break }
    $bytes = New-Object byte[] $size; (New-Object Random).NextBytes($bytes)
    $content = New-Object System.Net.Http.ByteArrayContent(,$bytes)
    $sw = [Diagnostics.Stopwatch]::StartNew(); $task = $hc.PostAsync($base + '/__up', $content)
    while (-not $task.IsCompleted) { Start-Sleep -Milliseconds 700; if (-not $task.IsCompleted) { $p = Ping-Once 900; if ($p -ge 0) { $upLoaded += $p } }; if ($sw.Elapsed.TotalSeconds -gt 30) { break } }
    $secs = [math]::Round($sw.Elapsed.TotalSeconds, 2); $spent += $secs
    if ($task.IsCompleted -and $task.Result.IsSuccessStatusCode) { $mb = To-Mbps $size $secs; ('  {0,5} MB in {1,5} s  = {2,7} Mbit/s' -f (To-MB $size), $secs, $mb); if ($size -ge $upBytes) { $upMbps = $mb; $upBytes = $size; $upSecs = $secs } } else { '  ' + (To-MB $size) + ' MB upload failed'; break }
    if ($secs -gt 4) { break }
  }
  if ($upBytes -gt 0) { 'Upload: ' + $upMbps + ' Mbit/s  (best of the sizes tried)' }
  ''
}
$dl = Avg $downLoaded; $ul = Avg $upLoaded
$worst = [math]::Max($dl, $ul); $bloat = -1; if ($idleAvg -ge 0 -and $worst -ge 0) { $bloat = $worst - $idleAvg }
$grade = ''; if ($bloat -ge 0) { if ($bloat -lt 30) { $grade = 'A - none' } elseif ($bloat -lt 100) { $grade = 'B - slight' } elseif ($bloat -lt 300) { $grade = 'C - noticeable (calls stutter while something downloads)' } else { $grade = 'D - severe (the connection stalls for others while one device transfers)' } }
if ($bloat -ge 0) { 'Latency under load: ' + (& { if ($dl -ge 0) { 'download ' + $dl + ' ms' } else { '' } }) + (& { if ($dl -ge 0 -and $ul -ge 0) { ', ' } else { '' } }) + (& { if ($ul -ge 0) { 'upload ' + $ul + ' ms' } else { '' } }) + ' vs ' + $idleAvg + ' ms idle (+' + $bloat + ' ms)  ->  bufferbloat grade ' + $grade }
''
'SUMMARY ' + ([pscustomobject]@{ colo = $colo; ip = $pubIp; idleMs = $idleAvg; jitterMs = $jit; httpMs = $httpMs; downMbps = $downMbps; downMB = (To-MB $downBytes); downSecs = $downSecs; upMbps = $upMbps; upMB = (To-MB $upBytes); upSecs = $upSecs; loadedDownMs = $dl; loadedUpMs = $ul; bloatMs = $bloat; grade = $grade } | ConvertTo-Json -Compress)

