$ErrorActionPreference = 'SilentlyContinue'
$doDown = $false; $doUp = $true; $downCap = 8; $upCap = 8
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
Add-Type -AssemblyName System.Net.Http
$hc = New-Object System.Net.Http.HttpClient; $hc.Timeout = [TimeSpan]::FromSeconds(60)
$base = 'https://speed.cloudflare.com'
function To-Mbps($bytes, $secs) { if ($secs -le 0) { return 0 }; return [math]::Round($bytes * 8 / 1000000 / $secs, 1) }
function To-MB($bytes) { return [math]::Round($bytes / 1000000, 1) }
function Ping-Once($ms) { try { $r = (New-Object System.Net.NetworkInformation.Ping).Send('1.1.1.1', $ms); if ($r.Status -eq 'Success') { return [int]$r.RoundtripTime } } catch { }; return -1 }
function Avg($a) { if ($a.Count) { return [int][math]::Round(($a | Measure-Object -Average).Average) }; return -1 }
# where the test server is, and how we look from outside
$colo = ''; $pubIp = ''
try { $trace = $hc.GetStringAsync($base + '/cdn-cgi/trace').Result; if ($trace -match '(?m)^colo=(\S+)') { $colo = $Matches[1] }; if ($trace -match '(?m)^ip=(\S+)') { $pubIp = $Matches[1] } } catch { }
if (-not $trace) { 'SPEED-ERROR: could not reach speed.cloudflare.com. Check the internet connection first ("Can''t reach the internet?" playbook).'; exit 1 }
'Speed test via Cloudflare' + (& { if ($colo) { ' (server ' + $colo + ')' } else { '' } }) + (& { if ($pubIp) { ', your public address ' + $pubIp } else { '' } })
# idle latency: ICMP to 1.1.1.1, and one HTTP round trip to the test server
$idle = @(); for ($i = 0; $i -lt 5; $i++) { $t = Ping-Once 1000; if ($t -ge 0) { $idle += $t }; Start-Sleep -Milliseconds 150 }
$sw = [Diagnostics.Stopwatch]::StartNew(); try { [void]$hc.GetByteArrayAsync($base + '/__down?bytes=0').Result } catch { }; $httpMs = [int]$sw.ElapsedMilliseconds
$idleAvg = Avg $idle; $jit = 0; if ($idle.Count -gt 1) { $jit = [int](($idle | Measure-Object -Maximum).Maximum - ($idle | Measure-Object -Minimum).Minimum) }
'Idle latency: ' + (& { if ($idleAvg -ge 0) { $idleAvg.ToString() + ' ms to 1.1.1.1 (jitter ' + $jit + ' ms)' } else { 'ping to 1.1.1.1 blocked' } }) + ', ' + $httpMs + ' ms server round trip'
''
$downMbps = 0; $downBytes = 0; $downSecs = 0; $downLoaded = @()
if ($doDown) {
  'Download (' + $downCap + ' s)'
  try {
    # Cloudflare serves at most ~100 MB per request, so ask for 25 MB repeatedly on one kept-alive connection until the time is up
    $buf = New-Object byte[] 262144; $sw = [Diagnostics.Stopwatch]::StartNew(); $total = [long]0; $tick = 1; $lastBytes = [long]0; $lastT = 0.0; $done = $false; $pt = $null
    while (-not $done) {
      $resp = $hc.GetAsync($base + '/__down?bytes=25000000', [System.Net.Http.HttpCompletionOption]::ResponseHeadersRead).Result
      if (-not $resp.IsSuccessStatusCode) { 'Download failed: HTTP ' + [int]$resp.StatusCode; break }
      $stream = $resp.Content.ReadAsStreamAsync().Result
      while (($n = $stream.Read($buf, 0, $buf.Length)) -gt 0) {
        $total += $n; $el = $sw.Elapsed.TotalSeconds
        if ($el -ge $tick) {
          # the ping runs in the background so a lost one never pauses the download; its answer is read at the next tick
          $p = -2; if ($pt) { if ($pt.Status -eq 'RanToCompletion' -and $pt.Result.Status -eq 'Success') { $p = [int]$pt.Result.RoundtripTime; $downLoaded += $p } else { $p = -1 } }
          $pt = (New-Object System.Net.NetworkInformation.Ping).SendPingAsync('1.1.1.1', 900)
          ('{0,3} s  {1,7} MB  {2,7} Mbit/s   {3,-1}' -f $tick, (To-MB $total), (To-Mbps ($total - $lastBytes) ($el - $lastT)), (& { if ($p -ge 0) { 'ping ' + $p + ' ms' } elseif ($p -eq -1) { 'ping lost' } else { '' } }))
          $lastBytes = $total; $lastT = $el; $tick++
        }
        if ($el -ge $downCap) { $done = $true; break }
      }
      $stream.Close(); $resp.Dispose()
    }
    $downSecs = [math]::Round($sw.Elapsed.TotalSeconds, 1); $downBytes = $total
  } catch { 'Download failed: ' + $_.Exception.Message }
  if ($downBytes -gt 0) { $downMbps = To-Mbps $downBytes $downSecs; 'Download: ' + $downMbps + ' Mbit/s  (' + (To-MB $downBytes) + ' MB in ' + $downSecs + ' s)' }
  ''
}
$upMbps = 0; $upBytes = 0; $upSecs = 0; $upLoaded = @()
if ($doUp) {
  'Upload (up to ' + $upCap + ' s)'
  $sizes = @(2000000, 8000000, 25000000, 60000000); $spent = 0.0
  foreach ($size in $sizes) {
    if ($spent -ge $upCap) { break }
    $bytes = New-Object byte[] $size; (New-Object Random).NextBytes($bytes)
    $content = New-Object System.Net.Http.ByteArrayContent(,$bytes)
    $sw = [Diagnostics.Stopwatch]::StartNew(); $task = $hc.PostAsync($base + '/__up', $content)
    while (-not $task.IsCompleted) { Start-Sleep -Milliseconds 700; if (-not $task.IsCompleted) { $p = Ping-Once 900; if ($p -ge 0) { $upLoaded += $p } }; if ($sw.Elapsed.TotalSeconds -gt 30) { break } }
    $secs = [math]::Round($sw.Elapsed.TotalSeconds, 2); $spent += $secs
    if ($task.IsCompleted -and $task.Result.IsSuccessStatusCode) { $mb = To-Mbps $size $secs; ('  {0,5} MB in {1,5} s  = {2,7} Mbit/s' -f (To-MB $size), $secs, $mb); if ($size -ge $upBytes) { $upMbps = $mb; $upBytes = $size; $upSecs = $secs } } else { '  ' + (To-MB $size) + ' MB upload failed'; break }
    if ($secs -gt 4) { break }
  }
  if ($upBytes -gt 0) { 'Upload: ' + $upMbps + ' Mbit/s  (best of the sizes tried)' }
  ''
}
$dl = Avg $downLoaded; $ul = Avg $upLoaded
$worst = [math]::Max($dl, $ul); $bloat = -1; if ($idleAvg -ge 0 -and $worst -ge 0) { $bloat = $worst - $idleAvg }
$grade = ''; if ($bloat -ge 0) { if ($bloat -lt 30) { $grade = 'A - none' } elseif ($bloat -lt 100) { $grade = 'B - slight' } elseif ($bloat -lt 300) { $grade = 'C - noticeable (calls stutter while something downloads)' } else { $grade = 'D - severe (the connection stalls for others while one device transfers)' } }
if ($bloat -ge 0) { 'Latency under load: ' + (& { if ($dl -ge 0) { 'download ' + $dl + ' ms' } else { '' } }) + (& { if ($dl -ge 0 -and $ul -ge 0) { ', ' } else { '' } }) + (& { if ($ul -ge 0) { 'upload ' + $ul + ' ms' } else { '' } }) + ' vs ' + $idleAvg + ' ms idle (+' + $bloat + ' ms)  ->  bufferbloat grade ' + $grade }
''
'SUMMARY ' + ([pscustomobject]@{ colo = $colo; ip = $pubIp; idleMs = $idleAvg; jitterMs = $jit; httpMs = $httpMs; downMbps = $downMbps; downMB = (To-MB $downBytes); downSecs = $downSecs; upMbps = $upMbps; upMB = (To-MB $upBytes); upSecs = $upSecs; loadedDownMs = $dl; loadedUpMs = $ul; bloatMs = $bloat; grade = $grade } | ConvertTo-Json -Compress)

run.command:
$ErrorActionPreference = 'SilentlyContinue'
$secs = 60
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$gw = ''; foreach ($r in @(Get-NetRoute -AddressFamily IPv4 -DestinationPrefix '0.0.0.0/0' | Sort-Object RouteMetric, InterfaceMetric)) { $a = @(Get-NetIPAddress -InterfaceIndex $r.InterfaceIndex -AddressFamily IPv4 | Where-Object { $_.IPAddress -notlike '169.254.*' -and $_.AddressState -eq 'Preferred' }); if ($a.Count) { $gw = $r.NextHop; break } }
$targets = @(); if ($gw) { $targets += @{ Name = 'router'; Host = $gw; Scale = @(2, 5, 10, 20, 50, 100, 200) } }
$targets += @{ Name = 'internet'; Host = '1.1.1.1'; Scale = @(20, 30, 50, 75, 100, 150, 250) }
foreach ($t in $targets) { $t.Sent = 0; $t.Lost = 0; $t.Ms = New-Object Collections.Generic.List[int]; $t.Run = 0; $t.RunStart = 0; $t.Bursts = @(); $t.Block = @() }
$bars = [char[]]@(0x2581, 0x2582, 0x2583, 0x2584, 0x2585, 0x2586, 0x2587, 0x2588)
function Stamp($s) { return ('{0,1}:{1:d2}' -f [math]::Floor($s / 60), ($s % 60)) }
function Spark($t) { $o = ''; foreach ($v in $t.Block) { if ($v -lt 0) { $o += [char]0x00D7 } else { $i = 0; foreach ($th in $t.Scale) { if ($v -gt $th) { $i++ } }; $o += $bars[$i] } }; return $o }
'Watching the connection for ' + [math]::Round($secs / 60, 1) + ' min: one ping a second to ' + (($targets | ForEach-Object { $_.Name + ' (' + $_.Host + ')' }) -join ' and ') + '. A line every 10 s; lost pings show as ' + [char]0x00D7 + ' in the bar, and runs of loss are called out.'
''
# one uncounted ping each first: the very first packet to a host waits for an ARP lookup and would count as a loss
foreach ($t in $targets) { try { [void](New-Object System.Net.NetworkInformation.Ping).Send($t.Host, 900) } catch { } }
$blockEvents = @()
for ($i = 1; $i -le $secs; $i++) {
  foreach ($t in $targets) { $t.Task = (New-Object System.Net.NetworkInformation.Ping).SendPingAsync($t.Host, 900); $t.Sent++ }
  Start-Sleep -Seconds 1
  foreach ($t in $targets) {
    $ok = ($t.Task.Status -eq 'RanToCompletion' -and $t.Task.Result.Status -eq 'Success')
    if ($ok) {
      $v = [int]$t.Task.Result.RoundtripTime; $t.Ms.Add($v); $t.Block += $v
      if ($t.Run -ge 2) { $t.Bursts += @{ At = $t.RunStart; Len = $t.Run }; $blockEvents += ('  ' + [char]0x26A0 + ' ' + (Stamp $t.RunStart) + '  ' + $t.Name + ': ' + $t.Run + ' pings lost in a row') }
      $t.Run = 0
    } else {
      $t.Lost++; $t.Block += -1; if ($t.Run -eq 0) { $t.RunStart = $i }; $t.Run++
    }
  }
  if ($i % 10 -eq 0 -or $i -eq $secs) {
    $parts = foreach ($t in $targets) { $good = @($t.Block | Where-Object { $_ -ge 0 }); $lost = @($t.Block | Where-Object { $_ -lt 0 }).Count; $avg = 0; $max = 0; if ($good.Count) { $avg = [int][math]::Round(($good | Measure-Object -Average).Average); $max = ($good | Measure-Object -Maximum).Maximum }; ('{0,-8} {1,4} ms  max {2,4}  {3,-1}' -f $t.Name, $avg, $max, (Spark $t)) + (& { if ($lost) { '  ' + $lost + ' lost' } else { '' } }) }
    ('{0,6}  ' -f (Stamp $i)) + ($parts -join '   |   ')
    foreach ($e in $blockEvents) { $e }; $blockEvents = @()
    foreach ($t in $targets) { $t.Block = @() }
  }
}
foreach ($t in $targets) { if ($t.Run -ge 2) { $t.Bursts += @{ At = $t.RunStart; Len = $t.Run }; '  ' + [char]0x26A0 + ' ' + (Stamp $t.RunStart) + '  ' + $t.Name + ': ' + $t.Run + ' pings lost in a row (still lost at the end)' } }
''
'Summary over ' + [math]::Round($secs / 60, 1) + ' min'
$sum = @{}
$rows = foreach ($t in $targets) {
  $avg = 0; $max = 0; $jit = 0
  if ($t.Ms.Count) { $avg = ($t.Ms | Measure-Object -Average).Average; $max = ($t.Ms | Measure-Object -Maximum).Maximum; $jit = ($t.Ms | ForEach-Object { [math]::Abs($_ - $avg) } | Measure-Object -Average).Average }
  $longest = 0; foreach ($b in $t.Bursts) { if ($b.Len -gt $longest) { $longest = $b.Len } }
  $pct = 0; if ($t.Sent) { $pct = [math]::Round(100 * $t.Lost / $t.Sent, 1) }
  $sum[$t.Name] = @{ sent = $t.Sent; lost = $t.Lost; pct = $pct; avg = [int][math]::Round($avg); max = [int]$max; jitter = [int][math]::Round($jit); bursts = $t.Bursts.Count; longest = $longest }
  [pscustomobject]@{ Target = $t.Name + ' (' + $t.Host + ')'; Sent = $t.Sent; Lost = $t.Lost; 'Loss %' = $pct; 'Avg ms' = [int][math]::Round($avg); 'Max ms' = [int]$max; 'Jitter ms' = [int][math]::Round($jit); Bursts = $t.Bursts.Count; 'Longest burst' = $longest }
}
($rows | Format-Table -AutoSize | Out-String -Width 4096).TrimEnd()
''
$r = $sum['router']; $n = $sum['internet']
$verdict = ''
if ($r -and ($r.bursts -ge 1 -or ($r.lost -ge 3 -and $r.pct -ge 1))) { $verdict = 'Dropouts on the local link: the router itself failed to answer ' + $r.lost + ' of ' + $r.sent + ' pings (' + $r.pct + '%' + (& { if ($r.bursts) { ', ' + $r.bursts + ' run' + (& { if ($r.bursts -ne 1) { 's' } else { '' } }) + ' of loss, longest ' + $r.longest + ' s' } else { '' } }) + '). That is between this PC and the router: Wi-Fi signal or interference, a cable, the adapter''s power saving, or the router rebooting.' }
elseif ($n.bursts -ge 1 -or ($n.lost -ge 3 -and $n.pct -ge 1)) { $verdict = 'Loss beyond the router: the router answered every ping but the internet lost ' + $n.lost + ' of ' + $n.sent + ' (' + $n.pct + '%' + (& { if ($n.bursts) { ', longest run ' + $n.longest + ' s' } else { '' } }) + '). The ISP link or further - worth showing the ISP.' }
elseif (($r -and $r.jitter -ge 10) -or $n.jitter -ge 30) { $verdict = 'No loss, but the delay wobbles (jitter ' + (& { if ($r) { 'router ' + $r.jitter + ' ms, ' } else { '' } }) + 'internet ' + $n.jitter + ' ms). Calls and games feel this even when pages load fine' + (& { if ($r -and $r.jitter -ge 10) { ' - and it starts on the local link, which usually means Wi-Fi.' } else { '.' } }) }
elseif (($r -and $r.lost) -or $n.lost) { $verdict = 'Essentially stable: a stray lost ping or two (' + (& { if ($r) { 'router ' + $r.lost + ', ' } else { '' } }) + 'internet ' + $n.lost + ') over ' + [math]::Round($secs / 60, 1) + ' min is normal.' }
else { $verdict = 'Stable: no lost pings and steady delay for ' + [math]::Round($secs / 60, 1) + ' min' + (& { if ($r) { ' (router ' + $r.avg + ' ms, internet ' + $n.avg + ' ms)' } else { '' } }) + '. If the connection still drops, it happens outside this window - run the longer variant when it is misbehaving.' }
$verdict
''
'SUMMARY ' + ([pscustomobject]@{ secs = $secs; gw = $gw; router = $r; internet = $n } | ConvertTo-Json -Compress -Depth 3)

