run.command:
$ErrorActionPreference = 'SilentlyContinue'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$listen = 3
$devices = @{}
function Dev($ip) { if (-not $script:devices.ContainsKey($ip)) { $script:devices[$ip] = @{ Names = @(); Models = @(); Makers = @(); Services = @(); Via = @{}; Hosts = @() } }; return $script:devices[$ip] }
# add a value once (case-insensitive); strips "(...)" wrappers and a trailing " [mac]"
function AddU($list, $v) { $v = ([string]$v).Trim() -replace '^\((.*)\)$', '$1' -replace '\s*\[[0-9a-fA-F:]+\]$', ''; if (-not $v) { return @($list) }; foreach ($x in $list) { if ($x -ieq $v) { return @($list) } }; return @($list) + $v }
# ---------- SSDP (UPnP): routers, TVs, media players, printers, NAS ----------
$ssdp = New-Object System.Net.Sockets.UdpClient
$ssdp.Client.SetSocketOption([System.Net.Sockets.SocketOptionLevel]::Socket, [System.Net.Sockets.SocketOptionName]::ReuseAddress, $true)
$ssdp.Client.Bind((New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Any, 0)))
$ssdp.Client.ReceiveTimeout = 400
$msearch = "M-SEARCH * HTTP/1.1`r`nHOST: 239.255.255.250:1900`r`nMAN: `"ssdp:discover`"`r`nMX: 2`r`nST: ssdp:all`r`n`r`n"
$mbytes = [Text.Encoding]::ASCII.GetBytes($msearch); $mep = New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Parse('239.255.255.250'), 1900)
[void]$ssdp.Send($mbytes, $mbytes.Length, $mep); Start-Sleep -Milliseconds 300; [void]$ssdp.Send($mbytes, $mbytes.Length, $mep)
$locations = @{}
$sw = [Diagnostics.Stopwatch]::StartNew()
while ($sw.Elapsed.TotalSeconds -lt $listen) {
  $from = New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Any, 0)
  try { $data = $ssdp.Receive([ref]$from) } catch { continue }
  $txt = [Text.Encoding]::ASCII.GetString($data); $ip = $from.Address.ToString(); $d = Dev $ip; $d.Via['SSDP'] = $true
  if ($txt -match '(?im)^LOCATION:\s*(\S+)') { $loc = $Matches[1]; if (-not $locations.ContainsKey($loc)) { $locations[$loc] = $ip } }
  if ($txt -match '(?im)^SERVER:\s*(.+?)\s*$') { $d.Services = AddU $d.Services ('UPnP: ' + ($Matches[1] -replace '\s+', ' ')) }
}
$ssdp.Close()
# device descriptions: the XML behind LOCATION carries the friendly name, maker and model
if ($locations.Count) {
  Add-Type -AssemblyName System.Net.Http
  $hc = New-Object System.Net.Http.HttpClient; $hc.Timeout = [TimeSpan]::FromSeconds(3)
  $tasks = @(); foreach ($loc in ($locations.Keys | Select-Object -First 25)) { $tasks += [pscustomobject]@{ Ip = $locations[$loc]; Task = $hc.GetStringAsync($loc) } }
  try { [void][System.Threading.Tasks.Task]::WaitAll([System.Threading.Tasks.Task[]]@($tasks | ForEach-Object { $_.Task }), 4000) } catch { }
  foreach ($t in $tasks) {
    if ($t.Task.Status -ne 'RanToCompletion') { continue }
    $x = $t.Task.Result; $d = Dev $t.Ip
    if ($x -match '<friendlyName>\s*([^<]+?)\s*</friendlyName>') { $d.Names = AddU $d.Names ([System.Net.WebUtility]::HtmlDecode($Matches[1])) }
    if ($x -match '<manufacturer>\s*([^<]+?)\s*</manufacturer>') { $d.Makers = AddU $d.Makers ([System.Net.WebUtility]::HtmlDecode($Matches[1])) }
    if ($x -match '<modelName>\s*([^<]+?)\s*</modelName>') { $d.Models = AddU $d.Models ([System.Net.WebUtility]::HtmlDecode($Matches[1])) }
    if ($x -match '<deviceType>\s*urn:[^:]+:device:([^:<]+)') { $d.Services = AddU $d.Services ('UPnP ' + $Matches[1]) }
  }
}
# ---------- mDNS / Bonjour: Apple, Google, printers, Sonos, HomeKit, Matter, smart TVs ----------
$types = @('_services._dns-sd._udp', '_http._tcp', '_printer._tcp', '_ipp._tcp', '_ipps._tcp', '_googlecast._tcp', '_airplay._tcp', '_raop._tcp', '_hap._tcp', '_matter._tcp', '_spotify-connect._tcp', '_smb._tcp', '_ssh._tcp', '_sonos._tcp', '_amzn-wplay._tcp', '_companion-link._tcp', '_androidtvremote2._tcp', '_workstation._tcp', '_device-info._tcp', '_homekit._tcp', '_hue._tcp', '_wled._tcp', '_esphomelib._tcp', '_miio._udp', '_dosvc._tcp', '_rdlink._tcp', '_afpovertcp._tcp', '_nvstream._tcp', '_viziocast._tcp', '_roku._tcp')
# PowerShell unrolls arrays returned from functions, hence the leading commas; bytes must be widened before shifting
function Enc-Name($n) { $b = New-Object System.Collections.Generic.List[byte]; foreach ($l in ($n.TrimEnd('.') -split '\.')) { $lb = [Text.Encoding]::UTF8.GetBytes($l); $b.Add([byte]$lb.Length); $b.AddRange($lb) }; $b.Add(0); return ,$b.ToArray() }
function Build-Query($names) { $b = New-Object System.Collections.Generic.List[byte]; $b.AddRange([byte[]]@(0, 0, 0, 0, 0, [byte]$names.Count, 0, 0, 0, 0, 0, 0)); foreach ($n in $names) { $b.AddRange([byte[]](Enc-Name $n)); $b.AddRange([byte[]]@(0, 12, 0x80, 1)) }; return ,$b.ToArray() }
function Read-Name($buf, [ref]$pos) { $parts = @(); $p = $pos.Value; $jumped = $false; $end = $p; $guard = 0; while ($guard++ -lt 64) { if ($p -ge $buf.Length) { break }; $len = [int]$buf[$p]; if ($len -eq 0) { $p++; break }; if (($len -band 0xC0) -eq 0xC0) { $ptr = (($len -band 0x3F) -shl 8) -bor [int]$buf[$p + 1]; if (-not $jumped) { $end = $p + 2 }; $jumped = $true; $p = $ptr; continue }; $p++; $parts += [Text.Encoding]::UTF8.GetString($buf, $p, $len); $p += $len }; if (-not $jumped) { $end = $p }; $pos.Value = $end; return ($parts -join '.') }
function U16($buf, $i) { return (([int]$buf[$i] -shl 8) -bor [int]$buf[$i + 1]) }
# Windows Firewall only lets the system resolver receive on port 5353, so we ask from an ordinary port with the
# "answer me directly" (QU) bit set: replies then come back unicast to us, which the firewall allows.
$m = New-Object System.Net.Sockets.UdpClient
$m.Client.Bind((New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Any, 0)))
$m.Client.ReceiveTimeout = 400
$mep = New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Parse('224.0.0.251'), 5353)
# one question per packet: some responders ignore multi-question queries
foreach ($ty in $types) { $q = Build-Query @($ty + '.local'); [void]$m.Send($q, $q.Length, $mep); Start-Sleep -Milliseconds 40 }
foreach ($ty in $types[0..5]) { $q = Build-Query @($ty + '.local'); [void]$m.Send($q, $q.Length, $mep); Start-Sleep -Milliseconds 40 }
$hostIp = @{}; $sw = [Diagnostics.Stopwatch]::StartNew(); $packets = 0
while ($sw.Elapsed.TotalSeconds -lt ($listen + 1)) {
  $from = New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Any, 0)
  try { $buf = $m.Receive([ref]$from) } catch { continue }
  if ($buf.Length -lt 12) { continue }
  $flags = U16 $buf 2; if (($flags -band 0x8000) -eq 0) { continue }   # only answers
  $packets++; $ip = $from.Address.ToString(); $d = Dev $ip; $d.Via['mDNS'] = $true
  $qd = U16 $buf 4; $an = (U16 $buf 6) + (U16 $buf 8) + (U16 $buf 10)
  $pos = 12
  for ($k = 0; $k -lt $qd; $k++) { [void](Read-Name $buf ([ref]$pos)); $pos += 4 }
  for ($k = 0; $k -lt $an; $k++) {
    if ($pos + 10 -gt $buf.Length) { break }
    $name = Read-Name $buf ([ref]$pos); $type = U16 $buf $pos; $pos += 8; $rdlen = U16 $buf $pos; $pos += 2; $rstart = $pos
    if ($type -eq 12) {
      $p2 = $pos; $target = Read-Name $buf ([ref]$p2)
      if ($target -match '^(.+?)\.(_[^.]+\._(tcp|udp))\.local$') {
        $svc = $Matches[2]; $inst = $Matches[1] -replace '\\032', ' ' -replace '\\(\d\d\d)', ''
        $d.Services = AddU $d.Services $svc
        # skip generic service names and machine-generated instance names such as "Chromecast-<32 hex>"
        if ($svc -notmatch '_services|_device-info|_companion-link|_rdlink|_dosvc' -and -not ($inst -match '^[A-Za-z]+-[0-9a-fA-F]+$' -and $inst.Length -gt 20)) { $d.Names = AddU $d.Names $inst }
      } elseif ($target -match '^(_[^.]+\._(tcp|udp))\.local$') { $d.Services = AddU $d.Services $Matches[1] }
    }
    elseif ($type -eq 33) { $p2 = $pos + 6; $target = Read-Name $buf ([ref]$p2); $d.Hosts = AddU $d.Hosts $target }
    elseif ($type -eq 16) { $p2 = $pos; while ($p2 -lt $rstart + $rdlen) { $l = [int]$buf[$p2]; if ($l -eq 0) { $p2++; continue }; $s = [Text.Encoding]::UTF8.GetString($buf, $p2 + 1, $l); $p2 += 1 + $l; if ($s -match '^(md|model|ty|am|manufacturer|product)=(.+)$') { $d.Models = AddU $d.Models $Matches[2] }; if ($s -match '^(fn|n)=(.+)$') { $d.Names = AddU $d.Names $Matches[2] } } }
    elseif ($type -eq 1 -and $rdlen -eq 4) { $a = ($buf[$pos..($pos + 3)] -join '.'); $hostIp[$name] = $a; if ($a -eq $ip) { $d.Hosts = AddU $d.Hosts $name } }
    $pos = $rstart + $rdlen
  }
}
$m.Close()
# hostnames from SRV records point at the device: use them as names when nothing friendlier came back
foreach ($ip in @($devices.Keys)) { $d = $devices[$ip]; foreach ($h in $d.Hosts) { $n = $h -replace '\.local$', ''; if (-not $d.Names.Count) { $d.Names = AddU $d.Names $n } } }
