$ErrorActionPreference = 'SilentlyContinue'
$secs = 10
$pr = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $pr.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { 'HUNT-ERROR: counting dropped packets needs administrator rights. Use "Run as admin" at the top of the window, then run this playbook again.'; exit 1 }
