if ($LASTEXITCODE -ne 0) { 'HUNT-ERROR: pktmon could not start. ' + (($started | Out-String).Trim()); exit 1 }
function Get-CountersJson { return (pktmon counters --json 2>&1 | Out-String) }
function Walk-Metrics($node, $prefix, $bag) {
  if ($node -is [pscustomobject]) {
    $props = $node.PSObject.Properties
    $tags = @(); foreach ($p in $props) { if ($p.Value -is [string] -and $p.Name -notmatch 'Reason|Name|Description') { $tags += $p.Value } }
    $pre = $prefix; if ($tags.Count) { $pre = (($prefix, ($tags -join '/')) | Where-Object { $_ }) -join '/' }
    foreach ($p in $props) {
      $v = $p.Value
      if ($v -is [string] -and $p.Name -match 'Reason' -and $v) { $bag.Reason = $v; continue }
      if ($p.Name -eq 'Id') { continue }
